"""
Codebase seed — Minimal Flask Todo API (tier 1, good seams)

A single-file Flask app with clean structure: models, routes, error handling.
Designed as a baseline for multi-session stories.
"""

from flask import Flask, request, jsonify
from datetime import datetime
import sqlite3
import os

app = Flask(__name__)

DATABASE = os.environ.get("DATABASE", "todos.db")
VALID_STATUSES = {"pending", "done"}


def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with get_db() as conn:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS tasks ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  title TEXT NOT NULL,"
            "  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'done')),"
            "  created_at TEXT NOT NULL"
            ")"
        )


# The API is usable when imported by a WSGI server or a test suite as well as
# when this module is run directly.
init_db()


# ── Models ────────────────────────────────────────────────────

def create_task(title: str) -> dict:
    with get_db() as conn:
        now = datetime.utcnow().isoformat()
        cursor = conn.execute(
            "INSERT INTO tasks (title, status, created_at) VALUES (?, 'pending', ?)",
            (title, now),
        )
        conn.commit()
        return {
            "id": cursor.lastrowid,
            "title": title,
            "status": "pending",
            "created_at": now,
        }


def get_tasks():
    with get_db() as conn:
        rows = conn.execute("SELECT * FROM tasks ORDER BY created_at DESC").fetchall()
        return [dict(r) for r in rows]


def get_task(task_id: int) -> dict | None:
    with get_db() as conn:
        row = conn.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone()
        return dict(row) if row else None


def update_task(task_id: int, title: str | None = None, status: str | None = None) -> dict | None:
    task = get_task(task_id)
    if task is None:
        return None
    if status is not None and status not in VALID_STATUSES:
        raise ValueError("status must be either 'pending' or 'done'")
    with get_db() as conn:
        updates = []
        params = []
        if title is not None:
            updates.append("title = ?")
            params.append(title)
        if status is not None:
            updates.append("status = ?")
            params.append(status)
        if updates:
            params.append(task_id)
            conn.execute(
                f"UPDATE tasks SET {', '.join(updates)} WHERE id = ?", params
            )
            conn.commit()
    return get_task(task_id)


# ── Routes ─────────────────────────────────────────────────────

@app.route("/tasks", methods=["GET"])
def list_tasks():
    return jsonify(get_tasks())


@app.route("/tasks", methods=["POST"])
def add_task():
    data = request.get_json(silent=True) or {}
    if not isinstance(data, dict):
        data = {}
    status = data.get("status")
    if status is not None and status not in VALID_STATUSES:
        return jsonify({"error": "status must be either 'pending' or 'done'"}), 422
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return jsonify({"error": "title is required"}), 400
    title = title.strip()
    task = create_task(title)
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
def show_task(task_id: int):
    task = get_task(task_id)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    if not isinstance(data, dict):
        data = {}
    status = data.get("status")
    if status is not None and status not in VALID_STATUSES:
        return jsonify({"error": "status must be either 'pending' or 'done'"}), 422
    title = data.get("title")
    if title is not None and (not isinstance(title, str) or not title.strip()):
        return jsonify({"error": "title must be a non-empty string"}), 400
    task = update_task(task_id, title=title.strip() if isinstance(title, str) else title, status=status)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


if __name__ == "__main__":
    init_db()
    app.run(debug=True)

import pytest

import app as app_module


@pytest.fixture
def client(tmp_path, monkeypatch):
    monkeypatch.setattr(app_module, "DATABASE", str(tmp_path / "tasks.db"))
    app_module.init_db()
    app_module.app.config.update(TESTING=True)
    with app_module.app.test_client() as test_client:
        yield test_client


def test_create_task_uses_pending_status_and_iso_timestamp(client):
    response = client.post("/tasks", json={"title": "Write tests"})

    assert response.status_code == 201
    task = response.get_json()
    assert task["title"] == "Write tests"
    assert task["status"] == "pending"
    assert task["id"] == 1
    assert "T" in task["created_at"]


def test_create_task_requires_title(client):
    response = client.post("/tasks", json={})

    assert response.status_code == 400
    assert response.get_json() == {"error": "title is required"}


def test_create_task_rejects_invalid_status(client):
    response = client.post("/tasks", json={"title": "Task", "status": "blocked"})

    assert response.status_code == 422
    assert response.get_json() == {
        "error": "status must be either 'pending' or 'done'"
    }


def test_list_tasks_is_ordered_newest_first(client):
    client.post("/tasks", json={"title": "First"})
    client.post("/tasks", json={"title": "Second"})

    response = client.get("/tasks")

    assert response.status_code == 200
    assert [task["title"] for task in response.get_json()] == ["Second", "First"]


def test_get_task_returns_404_for_missing_task(client):
    response = client.get("/tasks/99")

    assert response.status_code == 404
    assert response.get_json() == {"error": "task not found"}


def test_update_task_title_and_status(client):
    created = client.post("/tasks", json={"title": "Old title"}).get_json()

    response = client.put(
        f"/tasks/{created['id']}",
        json={"title": "New title", "status": "done"},
    )

    assert response.status_code == 200
    assert response.get_json()["title"] == "New title"
    assert response.get_json()["status"] == "done"


def test_invalid_status_is_rejected(client):
    created = client.post("/tasks", json={"title": "Task"}).get_json()

    response = client.put(f"/tasks/{created['id']}", json={"status": "blocked"})

    assert response.status_code == 422
    assert response.get_json() == {
        "error": "status must be either 'pending' or 'done'"
    }


def test_update_missing_task_returns_404(client):
    response = client.put("/tasks/99", json={"title": "Missing"})

    assert response.status_code == 404
    assert response.get_json() == {"error": "task not found"}

